INSERT INTO "bills" VALUES(10,'2271','Rządowy projekt ustawy o wykonywaniu orzeczeń Europejskiego Trybunału Praw Człowieka','2026-09-24T13:05:40+00:00','2026-09-04',1,'analyzed','["text:cudzoziemcy", "text:migracja", "text:uchodzcy", "text:straz_graniczna"]','{"term":10,"number":"2271","title":"Rządowy projekt ustawy o wykonywaniu orzeczeń Europejskiego Trybunału Praw Człowieka","description":"projekt dotyczy ustanowienia zasad i trybu wykonywania orzeczeń Europejskiego Trybunału Praw Człowieka, wydanych w sprawach ze skarg indywidualnych, w których stroną jest Rzeczpospolita Polska, w tym sposobu koordynacji współdziałania podmiotów publicznych w celu wykonania orzeczeń Trybunału.","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-02-13","document_date":"2026-02-13","change_date":"2026-09-24T13:05:40Z","closure_date":"2026-09-04","passed":true,"urgency_status":"NORMAL","eu_related":false,"prints_considered_jointly":[]}','[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2026-02-13","print_number":"2271","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania na posiedzeniu Sejmu","stage_type":"ReadingReferral","date":"2026-02-25","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-02-25","committee_code":"Sejm","sub_committee":false,"children":[]}]},{"stage_name":"I czytanie na posiedzeniu Sejmu","stage_type":"SejmReading","date":"2026-04-17","sitting_num":55,"sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-04-17","committee_code":"SPC","sub_committee":false,"children":[]},{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-04-17","committee_code":"SZA","sub_committee":false,"children":[]},{"stage_name":"Głosowanie","stage_type":"Voting","date":"2026-04-17","sub_committee":false,"voting":{"yes":201,"no":236,"abstain":0,"not_participating":23,"sitting":55,"voting_number":47,"date":"2026-04-17T08:36:14Z","pdf_url":"https://api.sejm.gov.pl/sejm/term10/votings/55/47/pdf","clubs":[]},"children":[]}]},{"stage_name":"Praca w komisjach po I czytaniu","stage_type":"CommitteeWork","date":"2026-07-31","sub_committee":false,"children":[{"stage_name":"Sprawozdanie komisji","stage_type":"CommitteeReport","date":"2026-07-31","print_number":"2843","report_file":"https://api.sejm.gov.pl/sejm/term10/prints/2843/2843.pdf","proposal":"załączony projekt ustawy","sub_committee":false,"children":[]}]},{"stage_name":"II czytanie na posiedzeniu Sejmu","stage_type":"SejmReading","date":"2026-09-02","sitting_num":64,"decision":"skierowano ponownie do komisji w celu przedstawienia sprawozdania","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-09-02","committee_code":"SPC","sub_committee":false,"children":[]},{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-09-02","committee_code":"SZA","sub_committee":false,"children":[]}]},{"stage_name":"Praca w komisjach po II czytaniu","stage_type":"CommitteeWork","date":"2026-09-04","sub_committee":false,"children":[{"stage_name":"Sprawozdanie komisji","stage_type":"CommitteeReport","date":"2026-09-04","print_number":"2843-A","report_file":"https://api.sejm.gov.pl/sejm/term10/prints/2843-A/2843-A.pdf","proposal":"odrzucić poprawkę","sub_committee":false,"children":[]}]},{"stage_name":"III czytanie na posiedzeniu Sejmu","stage_type":"SejmReading","date":"2026-09-04","sitting_num":64,"decision":"uchwalono","text_after3":"https://api.sejm.gov.pl/sejm/term10/processes/2271/attachment/2271_u3.pdf","sub_committee":false,"children":[{"stage_name":"Głosowanie","stage_type":"Voting","date":"2026-09-04","sub_committee":false,"voting":{"yes":241,"no":161,"abstain":38,"not_participating":20,"sitting":64,"voting_number":33,"date":"2026-09-04T09:50:01Z","pdf_url":"https://api.sejm.gov.pl/sejm/term10/votings/64/33/pdf","clubs":[]},"children":[]}]},{"stage_name":"Uchwalono","stage_type":"End","sub_committee":false,"children":[]}]','98d743006a0be259df4d996d7fac08bab0cafa83213228f5d16bef63332ac680','{"analysis":{"relevant":true,"score":2,"category":"indirect","summary":"Законопроект вводит правила исполнения решений Европейского суда по правам человека в Польше: кто отвечает за их выполнение, как выплачивается компенсация и как исполняются временные меры (например, приостановка высылки). Прямых изменений в правилах пребывания иностранцев нет, но механизм важен для тех, кто жалуется в ЕСПЧ.","key_changes":["МИД становится координатором исполнения решений ЕСПЧ, при нём создаётся межведомственная группа","Установлен порядок выплаты «справедливой компенсации» через заверенный формуляр платежа","Если формуляр не подан в срок, сумма вносится в судебный депозит","Окончательное решение ЕСПЧ прямо признаётся исполнительным документом (art. 777 KPC)","Суммы, назначенные ЕСПЧ, не подлежат взысканию также в пользу органов местного самоуправления","Порядок исполнения временных мер ЕСПЧ (в т.ч. приостановление решений органов) с уведомлением по телефону/e-mail в срочных делах"],"affected_groups":["лица, подавшие индивидуальные жалобы в ЕСПЧ против Польши, включая иностранцев","иностранцы, в отношении которых ЕСПЧ применил временную меру (например, против выдворения)","государственные органы Польши"],"practical_impact":"Заявитель (в том числе иностранец), получивший компенсацию от ЕСПЧ, будет получать от МИД заверенный формуляр платежа и обязан подать его в срок, иначе деньги внесут в судебный депозит. Временные меры ЕСПЧ, в том числе о приостановке высылки, должны исполняться госорганами незамедлительно, даже если сведения о них поступили от адвоката заявителя.","effective_date":"Закон вступает в силу через 30 дней после опубликования.","confidence":0.8,"rationale":"Закон процедурный и адресован госорганам, но косвенно значим для иностранцев из-за механизма исполнения временных мер ЕСПЧ (например, приостановление выдворения) и выплат компенсаций.","changes_since_previous":[]},"model":"claude-opus-5","prompt_version":"2026-09-v3","input_chars":155585,"truncated":false,"text_source":"pdf","created_at":"2026-09-09T17:58:41Z","input_tokens":76165,"output_tokens":773,"cache_read_input_tokens":2118,"cache_creation_input_tokens":0,"source_url":"https://api.sejm.gov.pl/sejm/term10/prints/2271/2271.pdf","source_kind":"print","revision":1}',0,NULL,'2026-09-07T13:52:14+00:00','2026-09-25T02:53:32+00:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-09-04',NULL,0,NULL,NULL,NULL);
