INSERT INTO "bills" VALUES(10,'2694','Rządowy projekt ustawy o zmianie ustawy o świadczeniu usług drogą elektroniczną oraz niektórych innych ustaw','2026-09-04T12:53:42','2026-09-04',1,'skipped_text_prefilter','["text:prawnicy_zagraniczni"]','{"term":10,"number":"2694","title":"Rządowy projekt ustawy o zmianie ustawy o świadczeniu usług drogą elektroniczną oraz niektórych innych ustaw","description":"projekt dotyczy ustanowienia Prezesa Urzędu Komunikacji Elektronicznej głównym organem nadzorującym stosowanie nowych przepisów i pełniącym funkcję koordynatora ds. usług cyfrowych; wprowadzenia nowych mechanizmów rozpatrywania sporów, zgłoszeń nielegalnych treści oraz dostępu do danych dużych platform internetowych, w celach naukowych dotyczących m.in. dezinformacji czy bezpieczeństwa w sieci","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-06-09","document_date":"2026-06-09","change_date":"2026-09-04T12:53:42","closure_date":"2026-09-04","passed":true,"urgency_status":"NORMAL","eu_related":false,"prints_considered_jointly":[]}',NULL,NULL,NULL,0,'text prefilter: under the threshold of 2 distinct patterns (prawnicy_zagraniczni×2)','2026-09-07T13:52:14+00:00','2026-09-07T13:52:14+00:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,NULL,NULL);
INSERT INTO "bills" VALUES(10,'2698','Rządowy projekt ustawy o zmianie ustawy o opiece nad dziećmi w wieku do lat 3 oraz niektórych innych ustaw','2026-08-27T11:21:36','2026-07-31',1,'analyzed','["text:migracja", "text:obywatelstwo", "text:straz_graniczna"]','{"term":10,"number":"2698","title":"Rządowy projekt ustawy o zmianie ustawy o opiece nad dziećmi w wieku do lat 3 oraz niektórych innych ustaw","description":"projekt dotyczy wprowadzenia nowej formy opieki - punkt opieki dziennej; wprowadzenia nowych uprawnień dla osób pracujących z najmłodszymi dziećmi (w tym m.in.: płatny czas na podnoszenie kwalifikacji zawodowych; 33-procentowa ulga na przejazdy publicznym transportem zbiorowym); nowe wymagania dotyczące plac zabaw przy żłobkach; propozycji ustanowienia 4 kwietnia Dniem Opiekuna Małego Dziecka","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-06-09","document_date":"2026-06-09","change_date":"2026-08-27T11:21:36","closure_date":"2026-07-31","passed":true,"urgency_status":"NORMAL","eu_related":false,"prints_considered_jointly":[]}','[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2026-06-09","print_number":"2698","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania na posiedzeniu Sejmu","stage_type":"ReadingReferral","date":"2026-06-17","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-06-17","committee_code":"Sejm","sub_committee":false,"children":[]}]},{"stage_name":"I czytanie na posiedzeniu Sejmu","stage_type":"SejmReading","date":"2026-07-02","sitting_num":61,"sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-07-02","committee_code":"PSR","sub_committee":false,"children":[]},{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-07-02","committee_code":"DIM","sub_committee":false,"children":[]}]},{"stage_name":"Praca w komisjach po I czytaniu","stage_type":"Commi