INSERT INTO "bills" VALUES(10,'2699','Rządowy projekt ustawy o zmianie ustawy o nabywaniu nieruchomości przez cudzoziemców oraz ustawy - Prawo o notariacie','2026-08-27T09:18:01+00:00','2026-07-17',1,'analyzed','["cudzoziemcy", "nieruchomosci_cudzoziemcy"]','{"term":10,"number":"2699","title":"Rządowy projekt ustawy o zmianie ustawy o nabywaniu nieruchomości przez cudzoziemców oraz ustawy - Prawo o notariacie","description":"projekt dotyczy usprawnienia kontroli nabywania przez cudzoziemców nieruchomości w Polsce. Notariusze będą przesyłać dokumenty do Ministerstwa Spraw Wewnętrznych i Administracji wyłącznie w formie elektronicznej. Dzięki temu ich obieg stanie się szybszy, bezpieczniejszy i bardziej przejrzysty. Zmiany wpisują się w proces cyfryzacji administracji publicznej i poprawiają nadzór nad zakupem nieruchomości przez cudzoziemców","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-06-09","document_date":"2026-06-09","change_date":"2026-08-27T09:18:01Z","closure_date":"2026-07-17","passed":true,"urgency_status":"NORMAL","eu_related":false,"rcl_num":"RM-0610-81-26","rcl_link":"https://legislacja.rcl.gov.pl/getIdFromLegislacja?number=RM-0610-81-26","prints_considered_jointly":[],"eli":"DU/2026/1099","display_address":"Dz.U. 2026 poz. 1099","isap_url":"https://isap.sejm.gov.pl/isap.nsf/DocDetails.xsp?id=WDU20260001099","stages":[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2026-06-09","print_number":"2699","sitting_num":null,"decision":null,"committee_code":null,"report_file":null,"text_after3":null,"position":null,"proposal":null,"sub_committee":false,"minority_motions":null,"voting":null,"committee_name":null,"children":[]},{"stage_name":"Skierowano do I czytania w komisjach","stage_type":"ReadingReferral","date":"2026-06-17","print_number":null,"sitting_num":null,"decision":null,"committee_code":null,"report_file":null,"text_after3":null,"position":null,"proposal":null,"sub_committee":false,"min