INSERT INTO "bills" VALUES(10,'2837','Rządowy projekt ustawy o zmianie ustawy o podatku dochodowym od osób fizycznych oraz ustawy o podatku dochodowym od osób prawnych','2026-09-24T13:11:27+00:00','2026-09-18',1,'skipped_text_prefilter','[]','{"term":10,"number":"2837","title":"Rządowy projekt ustawy o zmianie ustawy o podatku dochodowym od osób fizycznych oraz ustawy o podatku dochodowym od osób prawnych","description":"projekt dotyczy uproszczenia obowiązków informacyjnych dla przedsiębiorców dotyczących cen transferowych, czyli rozliczeń pomiędzy firmami należącymi do tej samej grupy kapitałowej. Nowe rozwiązania ograniczą obowiązki administracyjne, zmniejszą koszty prowadzenia działalności gospodarczej i ułatwią wywiązywanie się z obowiązków sprawozdawczych. Nowe przepisy realizują działania deregulacyjne rządu","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-07-22","document_date":"2026-07-22","change_date":"2026-09-24T13:11:27Z","closure_date":"2026-09-18","passed":true,"urgency_status":"NORMAL","eu_related":false,"prints_considered_jointly":[]}',NULL,NULL,NULL,0,'text prefilter: no keyword hits','2026-09-07T13:52:14+00:00','2026-09-25T02:53:32+00:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,NULL,NULL);
