INSERT INTO "bills" VALUES(10,'2870','Rządowy projekt ustawy o zmianie ustawy o działaniach antyterrorystycznych','2026-09-18T10:04:30+00:00','2026-09-18',1,'analyzed','["text:obywatelstwo", "text:straz_graniczna"]','{"term":10,"number":"2870","title":"Rządowy projekt ustawy o zmianie ustawy o działaniach antyterrorystycznych","description":"projekt dotyczy wprowadzenia stałych i jednolitych zasad przygotowania i zabezpieczania najważniejszych wydarzeń państwowych oraz międzynarodowych organizowanych w Polsce. Dzięki nowym przepisom służby będą mogły sprawniej planować działania i skuteczniej reagować na zagrożenia, w tym o charakterze terrorystycznym. Rozwiązania zastąpią przepisy przygotowywane dotychczas odrębnie dla poszczególnych wydarzeń","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-07-22","document_date":"2026-07-22","change_date":"2026-09-18T10:04:30Z","closure_date":"2026-09-18","passed":true,"urgency_status":"NORMAL","eu_related":false,"prints_considered_jointly":[]}','[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2026-07-22","print_number":"2870","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania w komisjach","stage_type":"ReadingReferral","date":"2026-07-29","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-07-29","committee_code":"ASW","sub_committee":false,"children":[]}]},{"stage_name":"I czytanie w komisjach","stage_type":"Reading","date":"2026-09-03","sub_committee":false,"children":[]},{"stage_name":"Praca w komisjach po I czytaniu","stage_type":"CommitteeWork","date":"2026-09-03","sub_committee":false,"children":[{"stage_name":"Sprawozdanie komisji","stage_type":"CommitteeReport","date":"2026-09-03","print_number":"3063","report_file":"https://api.sejm.gov.pl/sejm/term10/prints/3063/3063.pdf","proposal":"załączony projekt ustawy","sub_committee":false,"children":[]}]}]','b473964d27f4b3a7c2503e5cc3e11f467aa1