INSERT INTO "bills" VALUES(10,'2871','Senacki projekt ustawy o zmianie ustawy o wykonywaniu mandatu posła i senatora','2026-09-01T19:41:17',NULL,0,'skipped_text_prefilter','[]','{"term":10,"number":"2871","title":"Senacki projekt ustawy o zmianie ustawy o wykonywaniu mandatu posła i senatora","description":"projekt dotyczy : wskazania, że środki na odprawy rentowe lub emerytalne przysługujące pracownikom biur, klubów i kół oraz biur poselskich, senatorskich lub poselsko-senatorskich na podstawie Kodeksu pracy zapewnia się w budżetach Kancelarii Sejmu i Kancelarii Senatu, wyeliminowania przepisów stanowiących powtórzenie przepisów Konstytucji oraz posiadających brzmienie sprzeczne z treścią przepisów rangi konstytucyjnej (m.in. tekst roty ślubowania składanej przez posłów i senatorów), określenia kwoty darowizn ujawnianych przez posłów, senatorów lub ich małżonków w Rejestrze Korzyści oraz wykreślenia obowiązku bezpłatnego przekazywania posłom i senatorom papierowych druków sejmowych lub senackich","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-07-09","document_date":"2026-07-09","change_date":"2026-09-01T19:41:17","passed":false,"urgency_status":"NORMAL","eu_related":false,"prints_considered_jointly":[]}',NULL,NULL,NULL,0,'text prefilter: no keyword hits','2026-09-07T13:52:14+00:00','2026-09-07T13:52:14+00:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,NULL,NULL);
