INSERT INTO "bills" VALUES(10,'3010','Rządowy projekt ustawy o umorzeniu należności dochodzonych przez Zakład Ubezpieczeń Społecznych powstałych przed dniem 1 stycznia 1999 r.','2026-09-18T09:55:26+00:00','2026-09-18',1,'skipped_text_prefilter','[]','{"term":10,"number":"3010","title":"Rządowy projekt ustawy o umorzeniu należności dochodzonych przez Zakład Ubezpieczeń Społecznych powstałych przed dniem 1 stycznia 1999 r.","description":"projekt dotyczy umorzenia starych zobowiązań wobec ZUS. Chodzi o należności dotyczące składek powstałych przed 1 stycznia 1999 r., czyli przed reformą systemu ubezpieczeń społecznych. Nowe przepisy realizują działania deregulacyjne rządu","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-08-12","document_date":"2026-08-12","change_date":"2026-09-18T09:55:26Z","closure_date":"2026-09-18","passed":true,"urgency_status":"NORMAL","eu_related":false,"prints_considered_jointly":[]}',NULL,NULL,NULL,0,'text prefilter: no keyword hits','2026-09-07T13:52:14+00:00','2026-09-19T13:56:39+00:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,NULL,NULL);
INSERT INTO "bills" VALUES(10,'3011','Rządowy projekt ustawy o zmianie ustawy - Kodeks postępowania cywilnego','2026-09-18T09:46:36+00:00',NULL,0,'skipped_text_prefilter','[]','{"term":10,"number":"3011","title":"Rządowy projekt ustawy o zmianie ustawy - Kodeks postępowania cywilnego","description":"projekt dotyczy usprawnienia rozpatrywania spraw dotyczących ubezpieczeń społecznych. Sądy będą mogły w większej liczbie przypadków uchylić błędną decyzję organu rentowego, np. Zakładu Ubezpieczeń Społecznych, i przekazać sprawę do ponownego rozpatrzenia. Nowe przepisy realizują działania deregulacyjne rządu.","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-08-12","document_date":"2026-08-12","change_date":"2026-09-18T09:46:36Z","passed":false,"urgency_status":"NORMAL","eu_related":false,"prints_considered_jointly":[]}',NULL,NULL,NULL,0,'text prefilter: no keyword hits','2026-09-07T13:52:14+00:00','2026-09-19T13:56:39+00:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,NULL,NULL);
