4,"decision":"uchwalono","text_after3":"https://api.sejm.gov.pl/sejm/term10/processes/3015/attachment/3015_u3.pdf","sub_committee":false,"children":[{"stage_name":"Głosowanie","stage_type":"Voting","date":"2026-09-04","sub_committee":false,"voting":{"yes":439,"no":1,"abstain":0,"not_participating":20,"sitting":64,"voting_number":17,"date":"2026-09-04T09:34:32Z","pdf_url":"https://api.sejm.gov.pl/sejm/term10/votings/64/17/pdf","clubs":[]},"children":[]}]},{"stage_name":"Uchwalono","stage_type":"End","sub_committee":false,"children":[]}]','39ec39668ece47822a55ed42c7e71abd3a2537a8f8922cb97242b4f7ca8350b7','{"analysis":{"relevant":false,"score":1,"category":"none","summary":"Законопроект посвящён преобразованию Академии Мазовецкой в Университет Мазовецкий в Плоцке и вопросам организационной преемственности вуза, не затрагивая напрямую права или процедуры для иностранцев.","key_changes":[],"affected_groups":[],"practical_impact":"","effective_date":null,"confidence":0.85,"rationale":"Законопроект посвящён преобразованию Академии Мазовецкой в Университет Мазовецкий в Плоцке и вопросам организационной преемственности вуза, не затрагивая напрямую права или процедуры для иностранцев.","changes_since_previous":[]},"model":"claude-sonnet-5","prompt_version":"2026-09-v7","input_chars":0,"truncated":true,"text_source":"excerpts","created_at":"2026-09-15T13:51:22Z","input_tokens":13829,"output_tokens":110,"cache_read_input_tokens":null,"cache_creation_input_tokens":null,"source_url":null,"source_kind":"print","revision":1,"text_sha256":null,"source_checked_at":null}',0,NULL,'2026-09-07T13:52:14+00:00','2026-09-25T02:53:32+00:00',NULL,NULL,NULL,NULL,'{"representative":"Mirosław Orliński","representative_club":"PSL-TD","clubs":[["PSL-TD",21],["Lewica",4],["PiS",1]],"signatories":26,"unresolved":0}',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-09-04',NULL,0,NULL,NULL,NULL);
INSERT INTO "bills" VALUES(10,'3028','Rządowy projekt ustawy o zmianie ustawy o szczególnych rozwiązaniach służących realizacji ustawy budżetowej na rok 2026','2026-09-24T13:08:23+00:00','2026-09-04',1,'skipped_text_prefilter','[]','{"term":10,"number":"3028","title":"Rządowy projekt ustawy o zmianie ustawy o szczególnych rozwiązaniach służących realizacji ustawy budżetowej na rok 2026","description":"projekt dotyczy wprowadzenia rozwiązań umożliwiających sprawne wykonywanie budżetu państwa w 2026 r. w celu sfinansowania realizacji istotnych zadań publicznych w zakresie świadczeń wypłacanych z Funduszu emerytalno-rentowego","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-09-01","document_date":"2026-09-01","change_date":"2026-09-24T13:08:23Z","closure_date":"2026-09-04","passed":true,"urgency_status":"NORMAL","eu_related":false,"prints_considered_jointly":[]}',NULL,NULL,NULL,0,'text prefilter: no keyword hits','2026-09-07T13:52:14+00:00','2026-09-25T02:53:32+00:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,NULL,NULL);
INSERT INTO "bills" VALUES(10,'3029','Rządowy projekt ustawy o zmianie niektórych ustaw w celu ochrony rolniczych funkcji produkcyjnych wsi','2026-09-16T07:12:17+00:00',NULL,0,'analyzed','["text:migracja", "text:legalizacja"]','{"term":10,"number":"3029","title":"Rządowy projekt ustawy o zmianie niektórych ustaw w celu ochrony rolniczych funkcji produkcyjnych wsi","description":"projekt dotyczy wzmocnienia ochrony działalności rolniczej oraz ograniczenia konfliktów społecznych związanych m.in. z postępującą urbanizacją obszarów wiejskich. Rolnicy prowadzący działalność zgodnie z prawem zyskają większą pewność, że typowe uciążliwości związane z produkcją rolną, takie jak hałas, zapachy czy odgłosy zwierząt, nie będą podstawą do nieuzasadnionego ograniczania ich działalności. Projekt zakłada także lepsze informowanie osób kupujących nieruchomości na wsi o możliwych uciążliwościach związanych z działalnością rolniczą. Projekt realizuje priorytet polityki Rady Ministrów.","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-08-19","document_date":"2026-08-19","change_date":"2026-09-16T07:12:17Z","passed":false,"urgency_status":"NORMAL","eu_related":false,"prints_considered_jointly":[]}','[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2026-08-19","print_number":"3029","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania na posiedzeniu Sejmu","stage_type":"ReadingReferral","date":"2026-09-01","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-09-01","committee_code":"Sejm","sub_committee":false,"children":[]}]}]','c1faf8f84692362167a8d449b80dafb580b036907b58899768e03053dacd2122','{"analysis":{"relevant":false,"score":1,"category":"none","summary":"Проект касается ограничения конфликтов между сельскохозяйственной деятельностью и жителями деревень (шум, запахи от ферм) и изменений в Гражданском кодексе и законе о формировании аграрного строя, не затрагивая статус, права или обязанности иностранцев.","key_changes":[],"affected_groups":[],"practical_impact":"","effective_date":null,"confidence":0.9,"rationale":"Проект касается ограничения конфликтов между сельскохозяйственной деятельностью и жителями деревень (шум, запахи от ферм) и изменений в Гражданском кодексе и законе о формировании аграрного строя, не затрагивая статус, права или обязанности иностранцев.","changes_since_previous":[]},"model":"claude-sonnet-5","prompt_version":"2026-09-v3","input_chars":15924,"truncated":true,"text_source":"excerpts","created_at":"2026-09-09T18:00:47Z","input_tokens":9537,"output_tokens":128,"cache_read_input_tokens":null,"cache_creation_input_tokens":null,"source_url":null,"source_kind":"print","revision":1}',0,NULL,'2026-09-07T13:52:14+00:00','2026-09-17T10:08:11+00:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,NULL,NULL);
INSERT INTO "bills" VALUES(10,'3030','Rządowy projekt ustawy o usprawnieniu procesu inwestycyjnego w zakresie kluczowych inwestycji infrastrukturalnych','2026-09-21T10:02:00+00:00',NULL,0,'analyzed','["text:pobyt_kwalifikowany", "text:straz_graniczna"]','{"term":10,"number":"3030","title":"Rządowy projekt ustawy o usprawnieniu procesu inwestycyjnego w zakresie kluczowych inwestycji infrastrukturalnych","description":"projekt dotyczy przyspieszenia przygotowania i budowy najważniejszych inwestycji infrastrukturalnych, które mają znaczenie dla obronności Polski, bezpieczeństwa energetycznego, ochrony przeciwpowodziowej oraz rozwoju gospodarczego. Dla wybranych inwestycji zostaną wprowadzone prostsze procedury administracyjne, krótsze terminy oraz pierwszeństwo w rozpatrywaniu spraw przez urzędy. Projekt obejmuje zamknięty katalog konkretnych inwestycji m.in. \"Droga Czerwona\" w Gdyni zapewniająca dostęp do terminala w porcie, rozbudowa portów w Gdyni i Świnoujściu, inwestycje na lotniskach w Rzeszowie, Krakowie i Warszawie, a także rozbudowa ważnych połączeń kolejowych. Uproszczone procedury obejmą także inwestycje potrzebne do realizacji infrastruktury towarzyszącej elektrowni jądrowej na Pomorzu. Dotyczy to m.in. dróg, kolei i infrastruktury hydrotechnicznej","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-08-20","document_date":"2026-08-19","change_date":"2026-09-21T10:02:00Z","passed":false,"urgency_status":"NORMAL","eu_related":false,"prints_considered_jointly":[]}','[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2026-08-20","print_number":"3030","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania w komisjach","stage_type":"ReadingReferral","date":"2026-09-01","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-09-01","committee_code":"INF","sub_committee":false,"children":[]},{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-09-01","committee_code":"GMZ","sub_committee":false,"children":[]}]}]','21e120c3fcdd856406242c5de4786873fb7f9006a653c9cc5eb3fd3253c5b7b3','{"analysis":{"relevant":false,"score":1,"category":"none","summary":"Проект касается ускорения процедур реализации ключевых инфраструктурных инвестиций (дороги, порты, аэропорты, энергетика) и правил выкупа недвижимости под инвестиции, а упоминания Straży Granicznej и obywateli państw trzecich являются лишь описанием инфраструктуры аэропортов, не меняя прав или обязанностей иностранцев.","key_changes":[],"affected_groups":[],"practical_impact":"","effective_date":null,"confidence":0.85,"rationale":"Проект касается ускорения процедур реализации ключевых инфраструктурных инвестиций (дороги, порты, аэропорты, энергетика) и правил выкупа недвижимости под инвестиции, а упоминания Straży Granicznej и obywateli państw trzecich являются лишь описанием инфраструктуры аэропортов, не меняя прав или обязанностей иностранцев.","changes_since_previous":[]},"model":"claude-sonnet-5","prompt_version":"2026-09-v3","input_chars":17087,"truncated":true,"text_source":"excerpts","created_at":"2026-09-09T17:57:23Z","input_tokens":9938,"output_tokens":162,"cache_read_input_tokens":null,"cache_creation_input_tokens":null,"source_url":null,"source_kind":"print","revision":1}',0,NULL,'2026-09-07T13:52:14+00:00','2026-09-22T10:06:24+00:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,NULL,NULL);
