INSERT INTO "bills" VALUES(10,'RCL/12412802','Projekt ustawy o zmianie ustawy o świadczeniach opieki zdrowotnej finansowanych ze środków publicznych oraz niektórych innych ustaw','2026-09-24T00:00:00+00:00',NULL,NULL,'analyzed','["text:migracja", "text:obywatelstwo"]','{"term":10,"number":"RCL/12412802","title":"Projekt ustawy o zmianie ustawy o świadczeniach opieki zdrowotnej finansowanych ze środków publicznych oraz niektórych innych ustaw","description":"OCHRONA ZDROWIA; zdrowie","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-07-24","document_date":"2026-07-24","change_date":"2026-09-24T00:00:00Z","eu_related":false,"rcl_link":"https://legislacja.rcl.gov.pl/projekt/12412802","prints_considered_jointly":[],"applicant":"government"}','[{"stage_name":"2. Uzgodnienia","stage_type":"RclStage","sub_committee":false,"children":[]},{"stage_name":"3. Konsultacje publiczne","stage_type":"RclStage","sub_committee":false,"children":[]},{"stage_name":"9. Stały Komitet Rady Ministrów","stage_type":"RclStage","sub_committee":false,"children":[]}]','aa9e0817b5c511582d01f63d9a3d5f3b9bc2f4d01f88ec869e5eb3682922d489','{"analysis":{"relevant":false,"score":1,"category":"none","summary":"Ustawa dotyczy zatrudniania i wynagradzania personelu medycznego, kontroli NFZ oraz równego traktowania pacjentów (w tym niedyskryminacji ze względu na obywatelstwo/narodowość jako ogólna zasada), ale nie wprowadza odrębnych regulacji dotyczących pobytu, wiz, obywatelstwa ani szczególnych praw cudzoziemców.","key_changes":[],"affected_groups":[],"practical_impact":"","effective_date":null,"confidence":0.85,"rationale":"Ustawa dotyczy zatrudniania i wynagradzania personelu medycznego, kontroli NFZ oraz równego traktowania pacjentów (w tym niedyskryminacji ze względu na obywatelstwo/narodowość jako ogólna zasada), ale nie wprowadza odrębnych regulacji dotyczących pobytu, wiz, obywatelstwa ani szczególnych praw cudzoziemców.","changes_since_previous":[]},"model":