INSERT INTO "bills" VALUES(10,'RCL/12401003','Ustawa o opakowaniach i odpadach opakowaniowych','2026-09-23T00:00:00+00:00',NULL,NULL,'skipped_text_prefilter','["text:straz_graniczna"]','{"term":10,"number":"RCL/12401003","title":"Ustawa o opakowaniach i odpadach opakowaniowych","description":"OPAKOWANIA; klimat. Numer i tytuł aktu prawnego Unii Europejskiej: 1) rozporządzenie Parlamentu Europejskiego i Rady (UE) 2025/40 z dnia 19 grudnia 2024 r. w sprawie opakowań i odpadów opakowaniowych, zmiany rozporządzenia (UE) 2019/1020 i dyrektywy (UE) 2019/904 oraz uchylenia dyrektywy 94/62/WE (Dz. Urz. UE L, 2025/40, 22.01.2025); 2) dyrektywa Parlamentu Europejskiego i Rady 2008/98/WE z dnia 19 listopada 2008 r. w sprawie odpadów oraz uchylającą niektóre dyrektywy (Dz. Urz. UE L 312 z 22.11.2008, str. 3, Dz. Urz. UE L 365 z 19.12.2014, str. 89, Dz. Urz. UE L 21 z 28.01.2015, str. 22, Dz. Urz. UE L 184 z 11.07.2015, str. 13, Dz. Urz. UE L 297 z 13.11.2015, str. 9, Dz. Urz. UE L 42 z 18.02.2017, str. 43, Dz. Urz. UE L 150 z 14.06.2017, str. 1, Dz. Urz. UE L 150 z 14.06.2018, str. 109 i Dz. Urz. UE L 191 z 28.07.2023, str. 1)","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2025-08-13","document_date":"2026-07-08","change_date":"2026-09-23T00:00:00Z","eu_related":true,"rcl_link":"https://legislacja.rcl.gov.pl/projekt/12401003","prints_considered_jointly":[],"applicant":"government"}','[{"stage_name":"2. Uzgodnienia","stage_type":"RclStage","sub_committee":false,"children":[]},{"stage_name":"3. Konsultacje publiczne","stage_type":"RclStage","sub_committee":false,"children":[]},{"stage_name":"4. Opiniowanie","stage_type":"RclStage","sub_committee":false,"children":[]},{"stage_name":"6. Komitet do Spraw Europejskich","stage_type":"RclStage","date":"2026-07-08","sub_committee":false,"children":[]}]','cbe7bd7cd125082ce6b0f508554793058a1533ed41930cce0e789363effba42f',NULL,0,'text prefilter: weak patterns only (straz_graniczna×4)','2026-09-09T14:40: