cuments":[{"id":790457,"name":"RCL.pdf - odniesienie do uwag","url":"https://legislacja.rcl.gov.pl/docs//2/12404101/13168682/13168685/dokument790457.zip","created":"2026-08-03","author":"Departament Koordynacji Procesu Legislacyjnego"},{"id":791102,"name":"RCL (2).pdf - odniesienie do uwag","url":"https://legislacja.rcl.gov.pl/docs//2/12404101/13168682/13168685/dokument791102.pdf","created":"2026-08-06","author":"Departament Koordynacji Procesu Legislacyjnego"}]},{"id":13168686,"name":"Ustalenia Komitetu","documents":[]}],"catalog_read":true},{"id":13168687,"number":10,"name":"Komisja Prawnicza","state":"reached","modified":"2026-09-08","folders":[],"catalog_read":true},{"id":13168688,"number":11,"name":"Potwierdzenie projektu przez Stały Komitet Rady Ministrów","state":"not_started","folders":[],"catalog_read":false},{"id":13168693,"number":12,"name":"Rada Ministrów","state":"not_started","folders":[],"catalog_read":false},{"id":13168699,"number":13,"name":"Notyfikacja","state":"not_started","folders":[],"catalog_read":false},{"id":13168700,"number":14,"name":"Skierowanie projektu ustawy do Sejmu","state":"not_started","folders":[],"catalog_read":false}],"consultation":{"letter_url":"https://legislacja.rcl.gov.pl/docs//2/12404101/13168651/13168653/dokument747166.pdf","letter_date":"2025-11-08","days":21,"deadline":"2025-11-29","email":"sekretariat.dp@cyfra.gov.pl","positions":8,"response_published":false}}',NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,NULL,NULL);
INSERT INTO "bills" VALUES(10,'RCL/12413553','Projekt ustawy o zmianie ustawy o ochronie informacji niejawnych oraz ustawy o narodowym zasobie archiwalnym i archiwach','2026-09-18T00:00:00+00:00',NULL,NULL,'analyzed','["text:obywatelstwo", "text:straz_graniczna"]','{"term":10,"number":"RCL/12413553","title":"Projekt ustawy o zmianie ustawy o ochronie informacji niejawnych oraz ustawy o narodowym zasobie archiwalnym i archiwach","description":"OCHRONA INFORMACJI NIEJAWNYCH; inne","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-08-17","document_date":"2026-08-17","change_date":"2026-09-18T00:00:00Z","eu_related":false,"rcl_link":"https://legislacja.rcl.gov.pl/projekt/12413553","prints_considered_jointly":[],"applicant":"government"}','[{"stage_name":"2. Uzgodnienia","stage_type":"RclStage","sub_committee":false,"children":[]}]','e5f79696dfa493fc9fed66d5028ee4185f332f4b8e614eec24686b62545cac32','{"analysis":{"relevant":false,"score":1,"category":"none","summary":"Проект меняет ustawa o ochronie informacji niejawnych (закон о защите секретной информации) и закон об архивах: вводит особые правила на случай военного положения и зоны боевых действий. Касается учреждений, служб и предпринимателей, работающих с секретной информацией.","key_changes":["Новые определения: руководитель организационной единицы, военное положение, зона боевых действий","Приостановка проверочных процедур (postępowania sprawdzające) на время военного положения","Продление срока действия допусков и сертификатов до 6 месяцев после отмены военного положения","Упрощённый доступ к секретной информации по разрешению руководителя единицы","Разрешение уничтожать архивные материалы при невозможности эвакуации"],"affected_groups":["сотрудники учреждений с доступом к секретной информации","предприниматели, выполняющие контракты с гостайной"],"practical_impact":"Для иностранцев, проживающих в Польше, практически ничего не меняется; лишь упоминается возможность отказа от проверочной процедуры для лиц без польского гражданства при допуске к информации с грифом не выше \"poufne\" в зоне боевых действий.","effective_date":"Закон вступает в силу через 30 дней после публикации.","confidence":0.85,"rationale":"Тема — защита секретной информации и архивы; неграждане упомянуты лишь мимоходом в одном положении о допуске в условиях военного положения.","changes_since_previous":[]},"model":"claude-opus-5","prompt_version":"2026-09-v7","input_chars":77394,"truncated":false,"text_source":"documents","created_at":"2026-09-15T13:50:45Z","input_tokens":38710,"output_tokens":520,"cache_read_input_tokens":2496,"cache_creation_input_tokens":0,"source_url":"https://legislacja.rcl.gov.pl/docs//2/12413553/13221081/13221082/dokument792537.pdf","source_kind":"rcl","revision":1,"text_sha256":"2d69b90bbda899ac516b9a483744c828e6c0f70f7fe9aef3a8f26c05a8a111f9","source_checked_at":null}',0,NULL,'2026-09-09T14:41:28+00:00','2026-09-18T19:04:03+00:00',NULL,NULL,NULL,NULL,NULL,NULL,'{"id":12413553,"title":"Projekt ustawy o zmianie ustawy o ochronie informacji niejawnych oraz ustawy o narodowym zasobie archiwalnym i archiwach","applicant":"Minister-Członek Rady Ministrów Koordynator Służb Specjalnych","wykaz_number":"UD412","wykaz_url":"https://www.gov.pl/web/premier/wplip-rm","created":"2026-08-17","modified":"2026-09-08","departments":["inne"],"keywords":["OCHRONA INFORMACJI NIEJAWNYCH"],"status":"otwarty","term_label":"X","stages":[{"id":13221080,"number":1,"name":"Zgłoszenia lobbingowe","state":"not_started","folders":[],"catalog_read":false},{"id":13221081,"number":2,"name":"Uzgodnienia","state":"active","modified":"2026-09-08","folders":[{"id":13221082,"name":"Projekt","modified":"2026-08-17","documents":[{"id":792536,"name":"załącznik do pismo 07.08.2026 uzgodnienia [osr].pdf","url":"https://legislacja.rcl.gov.pl/docs//2/12413553/13221081/13221082/dokument792536.pdf","created":"2026-08-17","author":"Minister-Członek Rady Ministrów Koordynator Służb Specjalnych"},{"id":792537,"name":"załącznik do pismo 07.08.2026 uzgodnienia [projekt].pdf","url":"https://legislacja.rcl.gov.pl/docs//2/12413553/13221081/13221082/dokument792537.pdf","created":"2026-08-17","author":"Minister-Członek Rady Ministrów Koordynator Służb Specjalnych"},{"id":792538,"name":"załącznik do pismo 07.08.2026 uzgodnienia [uzasadnienie].pdf","url":"https://legislacja.rcl.gov.pl/docs//2/12413553/13221081/13221082/dokument792538.pdf","created":"2026-08-17","author":"Minister-Członek Rady Ministrów Koordynator Służb Specjalnych"}]},{"id":13221083,"name":"Pisma kierujące projekt do uzgodnień","modified":"2026-08-17","documents":[{"id":792539,"name":"pismo 07.08.2026 uzgodnienia.pdf","url":"https://legislacja.rcl.gov.pl/docs//2/12413553/13221081/13221083/dokument792539.pdf","created":"2026-08-17","author":"Minister-Członek Rady Ministrów Koordynator Służb Specjalnych"}]},{"id":13221084,"name":"Stanowiska zgłoszone w ramach uzgodnień","modified":"2026-09-08","documents":[{"id":794169,"name":"Stanowisko MSZ.pdf","url":"https://legislacja.rcl.gov.pl/docs//2/12413553/13221081/13221084/dokument794169.pdf","created":"2026-08-27","author":"Minister-Członek Rady Ministrów Koordynator Służb Specjalnych"},{"id":796109,"name":"uwagi ABW.pdf","url":"https://legislacja.rcl.gov.pl/docs//2/12413553/13221081/13221084/dokument796109.pdf","created":"2026-09-08","author":"Minister-Członek Rady Ministrów Koordynator Służb Specjalnych"},{"id":796110,"name":"uwagi KOSR.pdf","url":"https://legislacja.rcl.gov.pl/docs//2/12413553/13221081/13221084/dokument796110.pdf","created":"2026-09-08","author":"Minister-Członek Rady Ministrów Koordynator Służb Specjalnych"},{"id":796111,"name":"Uwagi MFiG (MRiT).pdf","url":"https://legislacja.rcl.gov.pl/docs//2/12413553/13221081/13221084/dokument796111.pdf","created":"2026-09-08","author":"Minister-Członek Rady Ministrów Koordynator Służb Specjalnych"},{"id":796112,"name":"uwagi MKiDN.pdf","url":"https://legislacja.rcl.gov.pl/docs//2/12413553/1322