INSERT INTO "bills" VALUES(10,'RCL/12413754','Projekt ustawy o zmianie ustawy o podatku dochodowym od osób fizycznych, ustawy o podatku dochodowym od osób prawnych oraz ustawy o zryczałtowanym podatku dochodowym od niektórych przychodów osiąganych przez osoby fizyczne','2026-09-24T00:00:00+00:00',NULL,NULL,'skipped_text_prefilter','[]','{"term":10,"number":"RCL/12413754","title":"Projekt ustawy o zmianie ustawy o podatku dochodowym od osób fizycznych, ustawy o podatku dochodowym od osób prawnych oraz ustawy o zryczałtowanym podatku dochodowym od niektórych przychodów osiąganych przez osoby fizyczne","description":"PODATKI; finanse publiczne","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-08-21","document_date":"2026-08-21","change_date":"2026-09-24T00:00:00Z","eu_related":false,"rcl_link":"https://legislacja.rcl.gov.pl/projekt/12413754","prints_considered_jointly":[],"applicant":"government"}','[{"stage_name":"2. Uzgodnienia","stage_type":"RclStage","sub_committee":false,"children":[]},{"stage_name":"3. Konsultacje publiczne","stage_type":"RclStage","sub_committee":false,"children":[]},{"stage_name":"4. Opiniowanie","stage_type":"RclStage","sub_committee":false,"children":[]}]','ef4cda679a7037b813f373b7cd31861f0979a3f6598c009490d08c3eb2a30d32',NULL,0,'text prefilter: no keyword hits','2026-09-09T14:41:28+00:00','2026-09-24T20:01:35+00:00',NULL,NULL,NULL,NULL,NULL,NULL,'{"id":12413754,"title":"Projekt ustawy o zmianie ustawy o podatku dochodowym od osób fizycznych, ustawy o podatku dochodowym od osób prawnych oraz ustawy o zryczałtowanym podatku dochodowym od niektórych przychodów osiąganych przez osoby fizyczne","applicant":"Minister Finansów i Gospodarki","wykaz_number":"UD458","wykaz_url":"https://www.gov.pl/web/premier/projekt-ustawy-o-zmianie-ustawy-o-podatku-dochodowym-od-osob-fizycznych-ustawy-o-podatku-dochodowym-od-osob-prawnych-oraz-ustawy-o-zryczaltowanym-podatku-dochodowym-od-niektorych-przychodow-osiaganych-przez-