,"catalog_read":false},{"id":13176294,"number":12,"name":"Rada Ministrów","state":"not_started","folders":[],"catalog_read":false},{"id":13176300,"number":13,"name":"Notyfikacja","state":"not_started","folders":[],"catalog_read":false},{"id":13176301,"number":14,"name":"Skierowanie projektu ustawy do Sejmu","state":"not_started","folders":[],"catalog_read":false}],"consultation":{"letter_url":"https://legislacja.rcl.gov.pl/docs//2/12405351/13176251/13176253/dokument754565.pdf","letter_date":"2025-12-16","days":21,"deadline":"2026-01-06","positions":2,"response_published":false},"consultation_attempts":1}',NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,NULL,NULL);
