INSERT INTO "bills" VALUES(10,'RCL/12412454','Projekt ustawy o zmianie ustawy o świadczeniach opieki zdrowotnej finansowanych ze środków publicznych oraz niektórych innych ustaw','2026-09-23T00:00:00+00:00',NULL,NULL,'analyzed','[]','{"term":10,"number":"RCL/12412454","title":"Projekt ustawy o zmianie ustawy o świadczeniach opieki zdrowotnej finansowanych ze środków publicznych oraz niektórych innych ustaw","description":"OCHRONA ZDROWIA; zdrowie","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-07-15","document_date":"2026-07-15","change_date":"2026-09-23T00:00:00Z","eu_related":false,"rcl_link":"https://legislacja.rcl.gov.pl/projekt/12412454","prints_considered_jointly":[],"applicant":"government"}','[{"stage_name":"9. Stały Komitet Rady Ministrów","stage_type":"RclStage","sub_committee":false,"children":[]},{"stage_name":"10. Komisja Prawnicza","stage_type":"RclStage","sub_committee":false,"children":[]}]','66d88d169102e19e52da404aac4787218c37ccb19281c80371592f67ecd30139','{"analysis":{"relevant":true,"score":2,"category":"indirect","summary":"Проект меняет правила медстрахования и возмещения расходов на лечение в странах ЕС/EFTA/Великобритании, уточняет обязанности получателей зарубежных пенсий и вводит статус центров редких болезней. Отдельно уточняется, что выпускники медицинских направлений, проходящие практическое обучение в Польше, подлежат медстрахованию.","key_changes":["Новая процедура возмещения NFZ расходов на необходимое лечение в ЕС/EFTA/UK по правилам координации","К заявлению на согласие NFZ можно приложить заключение врача из другой страны ЕС/EFTA с присяжным переводом","Возврат за лекарство по польскому рецепту на возмещение, а не только по трансграничному рецепту","Медстрахование для выпускников lekarski/lekarsko-dentystyczny, проходящих практическое обучение (art. 15p)","Обязанность сообщить в ZUS/KRUS об окончании работы за границей в течение 14 дней"],"affected_groups":["выпускники медицинских направлений, обучавшиеся не на польском языке и проходящие практику в Польше","лица, застрахованные в NFZ, лечащиеся в ЕС/EFTA/Великобритании","получатели пенсий из стран ЕС/EFTA/UK","члены семей застрахованных за границей","пациенты с редкими болезнями"],"practical_impact":"Для тех, кто лечится за границей, упрощается возврат расходов: принимаются электронные рецепты и направления, заключение зарубежного врача, перевод на счёт в SKOK или счёт третьего лица. Выпускники медвузов на практическом обучении получают ясное основание для медстрахования.","effective_date":"Через 14 дней после публикации; art. 1 pkt 9 lit. e и g и pkt 13 — через 12 месяцев после публикации; art. 1 pkt 25, art. 2 и art. 3 — с 1 января 2027 г.","confidence":0.72,"rationale":"Изменения касаются в основном общего механизма NFZ и координации в ЕС, для иностранцев влияние косвенное, за исключением уточнения страхования выпускников медицинских направлений.","changes_since_previous":[]},"model":"claude-opus-5","prompt_version":"2026-09-v7","input_chars":142467,"truncated":false,"text_source":"documents","created_at":"2026-09-15T15:47:50Z","input_tokens":70410,"output_tokens":789,"cache_read_input_tokens":0,"cache_creation_input_tokens":2496,"source_url":"https://legislacja.rcl.gov.pl/docs//2/12412454/13215491/13215492/dokument787723.zip","source_kind":"rcl","revision":1,"text_sha256":"dfec484a9a868e6268e22115dcaac3edf89a2e74d4a2904bd9d533a4635e54bd","source_checked_at":null}',0,NULL,'2026-09-14T20:21:01+00:00','2026-09-23T19:42:48+00:00',NULL,NULL,NULL,NULL,NULL,NULL,'{"id":12412454,"title":"Projekt ustawy o zmianie ustawy o świadczeniach opieki zdrowotnej finansowanych ze środków publicznych oraz niektórych innych ustaw","applicant":"Minister Zdrowia","wykaz_number":"UD428","wykaz_url":"https://www.gov.pl/web/premier/wplip-rm","created":"2026-07-15","modified":"2026-09-14","departments":["zdrowie"],"keywords":["OCHRONA ZDROWIA"],"status":"otwarty","term_label":"X","stages":[{"id":13215453,"number":1,"name":"