INSERT INTO "bills" VALUES(10,'RCL/12405005','Projekt ustawy o zmianie ustawy o Straży Granicznej oraz niektórych innych ustaw','2026-09-23T00:00:00+00:00',NULL,NULL,'analyzed','["text:cudzoziemcy", "text:migracja", "text:straz_graniczna", "text:granica_panstwowa", "text:schengen", "text:pracownicy_delegowani"]','{"term":10,"number":"RCL/12405005","title":"Projekt ustawy o zmianie ustawy o Straży Granicznej oraz niektórych innych ustaw","description":"STRAŻ GRANICZNA; sprawy wewnętrzne","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2025-12-08","document_date":"2026-09-14","change_date":"2026-09-23T00:00:00Z","eu_related":true,"rcl_link":"https://legislacja.rcl.gov.pl/projekt/12405005","prints_considered_jointly":[],"applicant":"government"}','[{"stage_name":"2. Uzgodnienia","stage_type":"RclStage","sub_committee":false,"children":[]},{"stage_name":"3. Konsultacje publiczne","stage_type":"RclStage","sub_committee":false,"children":[]},{"stage_name":"4. Opiniowanie","stage_type":"RclStage","sub_committee":false,"children":[]},{"stage_name":"6. Komitet do Spraw Europejskich","stage_type":"RclStage","date":"2026-03-25","sub_committee":false,"children":[]},{"stage_name":"9. Stały Komitet Rady Ministrów","stage_type":"RclStage","sub_committee":false,"children":[]},{"stage_name":"10. Komisja Prawnicza","stage_type":"RclStage","sub_committee":false,"children":[]},{"stage_name":"12. Rada Ministrów","stage_type":"RclStage","sub_committee":false,"children":[]}]','8217224cbdb8c1b22783ca43e2159355fc7395445a580aacab49f350f849dfff','{"analysis":{"relevant":true,"score":2,"category":"indirect","summary":"Проект приводит польские законы в соответствие с регламентом ЕС о Frontex. Он определяет полномочия Коменданта Главного Straży Granicznej, правила командирования польских пограничников в Frontex и регистрацию служебных машин Агентства. Для иностранцев значение имеет новая правовая база для операций и интервенций по возвращению (депортации), проводимых при поддержке Frontex на территории Польши.","key_changes":["В ustawa o cudzoziemcach вводятся понятия «operacja powrotowa» и «interwencja powrotowa» по регламенту ЕС 2019/1896","Новый art. 329b: Komendant Główny SG запрашивает и согласовывает операции возврата с участием Frontex в Польше","Сотрудники Frontex и погранслужб других стран ЕС смогут выполнять задачи по возвратам в Польше, включая применение силы","Komendant Główny SG назначается национальным контактным пунктом и координационным центром для Frontex (EUROSUR)","Frontex получит право регистрировать свои служебные автомобили и пользоваться статусом привилегированного транспорта"],"affected_groups":["иностранцы с решением о возврате (депортации)","лица, пересекающие внешнюю границу Польши","иностранцы без урегулированного статуса"],"practical_impact":"Процедуры депортации из Польши могут чаще проводиться в рамках совместных операций с Frontex, с участием иностранного персонала, имеющего право применять силу. На порядок выдачи разрешений на пребывание или работу проект не влияет.","effective_date":"Закон вступает в силу по истечении 14 дней со дня опубликования.","confidence":0.85,"rationale":"Проект в основном институциональный (Frontex, Straż Graniczna), но меняет ustawa o cudzoziemcach в части операций по возвращению, что косвенно затрагивает иностранцев.","changes_since_previous":[]},"model":"claude-opus-5","prompt_version":"2026-09-v7","input_chars":116489,"truncated":false,"text_source":"documents","created_at":"2026-09-14T20:21:47Z","input_tokens":55992,"output_tokens":697,"cache_read_input_tokens":2496,"cache_creation_input_tokens":0,"source_url":"https://legislacja.rcl.gov.pl/docs//2/12405005/13174615/13174616/dokument796916.zip","source_kind":"rcl","revision":1,"text_sha256":"3ef925cd0b4e25bcc121073127a2525eadd183dab133c4c6aed39031ece5f2e6","source_checked_at":null}',0,NULL,'2026-09-14T20:21:12+00:00','2026-09-23T19:42:48+00:00',NULL,NULL,NULL,NULL,NULL,NULL,'{"id":12405005,"title":"Projekt ustawy o zmianie ustawy o Straży Granicznej oraz niektórych innych ustaw","applicant":"Minister Spraw Wewnętrznych i Administracji","wykaz_number":"UC126","wykaz_url":"https://www.gov.pl/web/premier/wplip-rm","created":"2025-12-08","modified":"2026-09-14","departments":["sprawy wewnętrzne"],"keywords":["STRAŻ GRANICZNA"],"status":"otwarty","term_label":"X","stages":[{"id":13174566,"number":1,"name":"Zgłoszenia lobbingowe","state":"not_started","folders":[],"catalog_read":false},{"id":13174567,"number":2,"name":"Uzgodnienia","state":"reached","modified":"2025-12-08","folders":[],"catalog_read":false},{"id":13174573,"number":3,"name":"Konsultacje publiczne","state":"reached","modified":"2025-12-08","folders":[{"id":13174574,"name":"Projekt","modified":"2025-12-08","documents":[{"id":752655,"name":"Projekt","url":"https://legislacja.rcl.gov.pl/docs//2/12405005/13174573/13174574/dokument752655.docx","created":"2025-12-08","author":"Minister Spraw Wewnętrznych i Administracji"},{"id":752656,"name":"Uzasadnienie","url":"https://legislacja.rcl.gov.pl/docs//2/12405005/13174573/13174574/dokument752656.docx","created":"2025-12-08","author":"Minister Spraw Wewnętrznych i Administracji"},{"id":752657,"name":"OSR","url":"https://legislacja.rcl.gov.pl/docs//2/12405005/13174573/13174574/dokument752657.docx","created":"2025-12-08","author":"Minister Spraw Wewnętrznych i Administracji"},{"id":752658,"name":"Załącznik do OSR","url":"https://legislacja.rcl.gov.pl/docs//2/12405005/13174573/13174574/dokument752658.DOCX","created":"2025-12-08","author":"Minister Spraw Wewnętrznych i Administracji"}]},{"id":13174575,"name":"Pisma kierujące projekt do konsultacji publicznych","modified":"2025-12-08","documents":[{"id":752659,"name":"Pismo - stowarzyszenia i organizacje","url":"https://legislacja.rcl.gov.pl/docs//2/12405005/13174573/13174575/dokument752659.docx","created":"2025-12-08","author":"Minister Spraw Wewnętrznych i Administracji"},{"id":752660,"name":"Pismo - związki zawodowe","url"