INSERT INTO "bills" VALUES(10,'RCL/12405805','Projekt ustawy o zmianie niektórych ustaw w związku z rozwojem rejestrów publicznych prowadzonych z wykorzystaniem systemu rejestrów państwowych','2026-08-26T00:00:00+00:00',NULL,NULL,'analyzed','["text:cudzoziemcy", "text:obywatelstwo", "text:obywatele_ukrainy", "text:wizy", "text:zezwolenie_pobyt", "text:pobyt_kwalifikowany", "text:straz_graniczna", "text:zezwolenie_praca"]','{"term":10,"number":"RCL/12405805","title":"Projekt ustawy o zmianie niektórych ustaw w związku z rozwojem rejestrów publicznych prowadzonych z wykorzystaniem systemu rejestrów państwowych","description":"INFORMATYZACJA; informatyzacja","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-01-05","document_date":"2026-08-12","change_date":"2026-08-26T00:00:00Z","eu_related":false,"rcl_link":"https://legislacja.rcl.gov.pl/projekt/12405805","prints_considered_jointly":[],"applicant":"government"}','[{"stage_name":"2. Uzgodnienia","stage_type":"RclStage","sub_committee":false,"children":[]},{"stage_name":"3. Konsultacje publiczne","stage_type":"RclStage","sub_committee":false,"children":[]},{"stage_name":"4. Opiniowanie","stage_type":"RclStage","sub_committee":false,"children":[]},{"stage_name":"5. Komitet Rady Ministrów do Spraw Cyfryzacji","stage_type":"RclStage","sub_committee":false,"children":[]},{"stage_name":"9. Stały Komitet Rady Ministrów","stage_type":"RclStage","sub_committee":false,"children":[]}]','4b7bdc5003b7c420798fa4867be8db79e626503b7a0a19716d1d3ffe879fe6af','{"analysis":{"relevant":true,"score":3,"category":"social","summary":"Проект изменяет правила ведения реестров PESEL, актов гражданского состояния и паспортного реестра. Для иностранцев ключевое: нельзя будет получить номер PESEL только ради подтверждения profil zaufany, а в реестре PESEL начнут хранить вид проездного документа. Также упрощается выписка (wymeldowanie) в любой гмине.","key_changes":["Обязанность указать PESEL для profil zaufany перестаёт быть основанием для присвоения номера PESEL","В реестре PESEL добавляется запись о виде проездного документа/документа личности иностранца","Wymeldowanie и заявление о выезде за границу можно будет подать в органе любой гмины","Снятие блокировки (zastrzeżenie) номера PESEL через представителя по нотариальной или адвокатской доверенности","Электронная услуга возврата к добрачной фамилии после развода через kierownik USC"],"affected_groups":["Иностранцы, обращающиеся за PESEL в консульствах и вне Польши","Иностранцы, проживающие в Польше и имеющие PESEL","Граждане Украины (обмен данными с Strażą Graniczną)","Разведённые лица, желающие вернуть добрачную фамилию"],"practical_impact":"Получить PESEL, обосновывая заявление лишь необходимостью оформить profil zaufany, станет невозможно; PESEL по-прежнему будет присваиваться при прописке, работе, налогах и по иным отдельным нормам. Выписаться с адреса можно будет в любой гмине, а данные о виде паспорта иностранца попадут в реестр PESEL.","effective_date":"Через 14 дней после опубликования, кроме: art. 2 пункты 1, 2, 10 и 11 — с 1 февраля 2028 г.; art. 1 и 3 — с 1 января 2030 г.","confidence":0.85,"rationale":"Проект напрямую затрагивает условия присвоения PESEL иностранцам и объём хранимых о них данных, что относится к административно-социальной сфере, а не к легализации пребывания.","changes_since_previous":[]},"model":"claude-opus-5","prompt_version":"2026-09-v7","input_chars":40876,"truncated":false,"text_source":"documents","created_at":"2026-09-15T01:42:00Z","input_tokens":20581,"output_tokens":750,"cache_read_input_tokens":0,"cache_creation_input_tokens":2496,"source_url":"https://legislacja.rcl.gov.pl/docs//2/12405805/13178996/13178997/dokument791976.zip","source_kind":"rcl","revision":1,"text_sha256":"a8037bb15ec20456c90879953e87c7e2fba4437de227fab8b6021e26e0d8780d","source_checked_at":null}',0,NULL,'2026-09-15T01:39:30+00:00','2026-09-24T08:48:22+00:00',NULL,NULL,NULL,NULL,NULL,NULL,'{"id":12405805,"title":"Projekt ustawy o zmianie niektórych ustaw w związku z rozwojem rejestrów publicznych prowadzonych z wykorzystaniem systemu rejestrów państwowych","applicant":"Minister Cyfryzacji","wykaz_number":"UD337","wykaz_url":"https://www.gov.pl/web/premier/wplip-rm","created":"2026-01-05","modified":"2026-08-26","departments":["informatyzacja"],"keywords":["INFORMATYZACJA"],"status":"otwarty","term_label":"X","stages":[{"id":13178958,"number":1,"name":"Zgłoszenia lobbingowe","state":"not_started","folders":[],"catalog_read":false},{"id":13178959,"number":2,"name":"Uzgodnienia","state":"reached","modified":"2026-03-16","folders":[{"id":13178960,"name":"Projekt","modified":"2026-03-16","documents":[{"id":757341,"name":"Projekt SRP z OSR 02012026.docx","url":"https://legislacja.rcl.gov.pl/docs//2/12405805/13178959/13178960/dokument757341.docx","created":"2026-01-05","author":"Minister Cyfryzacji"},{"id":767378,"name":"projekt ustawy SRP po uzg _ust.docx","url":"https://legislacja.rcl.gov.pl/docs//2/12405805/13178959/13178960/dokument767378.docx","created":"2026-03-16","author":"Minister Cyfryzacji"}]},{"id":13178961,"name":"Pisma kierujące projekt do uzgodnień","modified":"2026-03-16","documents":[{"id":757343,"name":"Pismo uzgodnienia SRP.pdf","url":"https://legislacja.rcl.gov.pl/docs//2/12405805/13178959/13178961/dokument757343.pdf","created":"2026-01-05","author":"Minister Cyfryzacji"},{"id":767379,"name":"Pismo zakończenie uzgodnień.pdf","url":"https://legislacja.rcl.gov.pl/docs//2/12405805/13178959/13178961/dokument767379.pdf","created":"2026-03-16","author":"Minister Cyfryzacji"}]},{"id":13178962,"name":"Stanowiska zgłoszone w ramach uzgodnień","modified":"2026-03-16","documents":[{"id":767382,"name":"SRP_tabela uwag_uzgodnienia _ost.docx","url":"https://legislacja.rcl.gov.pl/docs//2/12405805/13178959/13178962/dokument767382.docx","created":"2026-03-16","author":"Minister Cyfryzacji"}]},{"id":13178963,"name":"Odniesienie się wnioskodawcy do uwag","documents":[]},{"id":1