INSERT INTO "bills" VALUES(10,'RCL/12399650','Projekt ustawy o kredycie konsumenckim','2026-06-12T00:00:00+00:00',NULL,NULL,'skipped_text_prefilter','[]','{"term":10,"number":"RCL/12399650","title":"Projekt ustawy o kredycie konsumenckim","description":"KONSUMENCI; inne. Numer i tytuł aktu prawnego Unii Europejskiej: dyrektywa Parlamentu Europejskiego i Rady (UE) 2023/2225 z dnia 18 października 2023 r. w sprawie umów o kredyt konsumencki oraz uchylająca dyrektywę 2008/48/WE oraz dyrektywa Parlamentu Europejskiego i Rady (UE) 2023/2673 z dnia 22 listopada 2023 r. zmieniająca dyrektywę 2011/83/UE w odniesieniu do umów o usługi finansowe zawieranych na odległość oraz uchylająca dyrektywę 2002/65/WE","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2025-07-07","document_date":"2026-05-18","change_date":"2026-06-12T00:00:00Z","eu_related":true,"rcl_link":"https://legislacja.rcl.gov.pl/projekt/12399650","prints_considered_jointly":[],"applicant":"government"}','[{"stage_name":"2. Uzgodnienia","stage_type":"RclStage","sub_committee":false,"children":[]},{"stage_name":"3. Konsultacje publiczne","stage_type":"RclStage","sub_committee":false,"children":[]},{"stage_name":"4. Opiniowanie","stage_type":"RclStage","sub_committee":false,"children":[]},{"stage_name":"6. Komitet do Spraw Europejskich","stage_type":"RclStage","sub_committee":false,"children":[]}]','9cd4a3f340b64214f9b5f46997785915565db1f1ec4948beadc19fef099cecc0',NULL,0,'text prefilter: no keyword hits','2026-09-15T01:41:31+00:00','2026-09-15T01:41:31+00:00',NULL,NULL,NULL,NULL,NULL,NULL,'{"id":12399650,"title":"Projekt ustawy o kredycie konsumenckim","applicant":"Prezes Urzędu Ochrony Konkurencji i Konsumentów","wykaz_number":"UC82","wykaz_url":"https://www.gov.pl/web/premier/projekt-ustawy-o-kredycie-konsumenckim-oraz-o-zmianie-ustawy-o-prawach-konsumenta","created":"2025-07-07","modified":"2026-06-12","departments":["inne"],"keywords":["KONSUMENCI"],"status":"otwarty","eu_note":"