INSERT INTO "bills" VALUES(10,'2642','Rządowy projekt ustawy o zmianie ustawy - Prawo bankowe oraz niektórych innych ustaw','2026-09-15T06:47:54+00:00','2026-07-31',1,'analyzed','["text:obywatelstwo", "text:legalizacja", "text:straz_graniczna"]','{"term":10,"number":"2642","title":"Rządowy projekt ustawy o zmianie ustawy - Prawo bankowe oraz niektórych innych ustaw","description":"projekt dotyczy zmiany zasad dotyczących powoływania członków organów zarządzających dużymi bankami, nadania Komisji Nadzoru Finansowego nowych uprawnień dotyczących nadzoru nad istotnymi transakcjami prowadzonymi przez banki, uregulowania zasad działania w Polsce oddziałów banków z państw trzecich, mających siedzibę poza Unią Europejską, wprowadzenia zasad zapobiegających konfliktowi interesów po zakończeniu pełnienia funkcji Przewodniczącego KNF i jego zastępców oraz po zakończeniu pracy przez pracowników KNF","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-06-02","document_date":"2026-06-02","change_date":"2026-09-15T06:47:54Z","closure_date":"2026-07-31","passed":true,"urgency_status":"NORMAL","eu_related":true,"prints_considered_jointly":[],"eli":"DU/2026/1206","display_address":"Dz.U. 2026 poz. 1206","isap_url":"https://isap.sejm.gov.pl/isap.nsf/DocDetails.xsp?id=WDU20260001206"}','[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2026-06-02","print_number":"2642","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania na posiedzeniu Sejmu","stage_type":"ReadingReferral","date":"2026-06-09","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-06-09","committee_code":"Sejm","sub_committee":false,"children":[]}]},{"stage_name":"I czytanie na posiedzeniu Sejmu","stage_type":"SejmReading","date":"2026-06-19","sitting_num":60,"sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-06-19","committee_code":"FPB","sub_commi