INSERT INTO "bills" VALUES(10,'3088','Rządowy projekt ustawy o zmianie ustawy o postępowaniu w sprawach dotyczących pomocy publicznej oraz niektórych innych ustaw','2026-09-15T08:56:11+00:00',NULL,0,'analyzed','["text:migracja", "text:granica_panstwowa"]','{"term":10,"number":"3088","title":"Rządowy projekt ustawy o zmianie ustawy o postępowaniu w sprawach dotyczących pomocy publicznej oraz niektórych innych ustaw","description":"projekt dotyczy zniesienia obowiązku przedstawiania zaświadczeń lub oświadczeń dotyczących udzielonej pomocy de minimis i pomocy de minimis w rolnictwie lub rybołówstwie przez podmioty ubiegające się o taką pomoc, jaki obecnie ciąży na nich zgodnie z art. 37 ust. 1 i 2 ustawy z dnia 30 kwietnia 2004 r. o postępowaniu w sprawach dotyczących pomocy publicznej. Nowe przepisy realizują działania deregulacyjne Rządu.","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-09-10","document_date":"2026-09-10","change_date":"2026-09-15T08:56:11Z","passed":false,"urgency_status":"NORMAL","eu_related":false,"prints_considered_jointly":[]}','[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2026-09-10","print_number":"3088","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania w komisjach","stage_type":"ReadingReferral","date":"2026-09-15","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-09-15","committee_code":"GOR","sub_committee":false,"children":[]},{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-09-15","committee_code":"DER","sub_committee":false,"children":[]}]}]','b42102f2f8490db991b8e2e73c9d889e4644e00205065cd66e681cda1ac17a4c','{"analysis":{"relevant":false,"score":1,"category":"none","summary":"Проект касается дерегуляции процедур получения помощи de minimis (отмена справок/заявлений) и технических изменений в ряде законов, включая закон об охране государственной границы, но не затрагивает права, обязанности или процедуры для иностранцев.","key_changes":[],"affected_groups":[],"practical_impact":"","effective_date":null,"confidence":0.9,"rationale":"Проект касается дерегуляции процедур получения помощи de minimis (отмена справок/заявлений) и технических изменений в ряде законов, включая закон об охране государственной границы, но не затрагивает права, обязанности или процедуры для иностранцев.","changes_since_previous":[]},"model":"claude-sonnet-5","prompt_version":"2026-09-v7","input_chars":11752,"truncated":true,"text_source":"excerpts","created_at":"2026-09-15T11:31:49Z","input_tokens":7520,"output_tokens":116,"cache_read_input_tokens":null,"cache_creation_input_tokens":null,"source_url":null,"source_kind":"print","revision":1,"text_sha256":null,"source_checked_at":null}',0,NULL,'2026-09-15T10:13:53+00:00','2026-09-16T10:05:08+00:00','{"term":10,"number":"RPW/30305/2026","title":"Rządowy projekt ustawy o zmianie ustawy o postępowaniu w sprawach dotyczących pomocy publicznej oraz niektórych innych ustaw","description":"zniesienia obowiązku przedstawiania zaświadczeń lub oświadczeń dotyczących udzielonej pomocy de minimis i pomocy de minimis w rolnictwie lub rybołówstwie przez podmioty ubiegające się o taką pomoc, jaki obecnie ciąży na nich zgodnie z art. 37 ust. 1 i 2 ustawy z dnia 30 kwietnia 2004 r. o postępowaniu w sprawach dotyczących pomocy publicznej. Nowe przepisy realizują działania deregulacyjne Rządu.","applicant":"government","status":"ACTIVE","submission_type":"BILL","date_of_receipt":"2026-09-10","print_number":null,"eu_related":false,"public_consultation":false,"consultation_start":null,"consultation_end":null,"consultation_results":false,"withdrawn_date":null}','RPW/30305/2026',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,NULL,NULL);
