INSERT INTO "bills" VALUES(10,'2007','Poselski projekt ustawy o zmianie ustawy o wychowaniu w trzeźwości i przeciwdziałaniu alkoholizmowi oraz ustawy o świadczeniach opieki zdrowotnej finansowanych ze środków publicznych','2026-09-17T19:14:42+00:00',NULL,0,'analyzed','[]','{"term":10,"number":"2007","title":"Poselski projekt ustawy o zmianie ustawy o wychowaniu w trzeźwości i przeciwdziałaniu alkoholizmowi oraz ustawy o świadczeniach opieki zdrowotnej finansowanych ze środków publicznych","description":"projekt dotyczy ograniczenia nadmiernej dostępności alkoholu i przeciwdziałanie jego promocji poprzez m.in całkowity zakaz reklamy i promocji wszystkich napojów alkoholowych, w tym piwa; zakaz sprzedaży alkoholu na stacjach paliw, w zakładach leczniczych oraz w godzinach nocnych na terenie całego kraju (22-6), wprowadzenie obowiązku weryfikacji wieku przy zakupie; zakaz sprzedaży alkoholu poniżej sumy podatku akcyzowego i VAT; uregulowanie sprzedaży internetowej wyłącznie z odbiorem osobistym po okazaniu dokumentu tożsamości","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2025-09-23","document_date":"2025-09-22","change_date":"2026-09-17T19:14:42Z","passed":false,"urgency_status":"NORMAL","eu_related":false,"prints_considered_jointly":["2010"]}','[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2025-09-23","print_number":"2007","sub_committee":false,"children":[]},{"stage_name":"Opinia organizacji samorządowej","stage_type":"Opinion","date":"2025-10-01","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania na posiedzeniu Sejmu","stage_type":"ReadingReferral","date":"2025-12-05","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2025-12-05","committee_code":"Sejm","sub_committee":false,"children":[]}]},{"stage_name":"I czytanie na posiedzeniu Sejmu","stage_type":"SejmReading","date":"2026-01-23","sitting_num":50,"sub_committee":false,"children":[