INSERT INTO "bills" VALUES(10,'3100','Rządowy projekt ustawy o podatku od nadzwyczajnych zysków osiągniętych w okresie od marca do grudnia 2026 r. ze zbycia paliw ciekłych','2026-09-24T13:09:30+00:00','2026-09-18',1,'skipped_text_prefilter','[]','{"term":10,"number":"3100","title":"Rządowy projekt ustawy o podatku od nadzwyczajnych zysków osiągniętych w okresie od marca do grudnia 2026 r. ze zbycia paliw ciekłych","description":"projekt dotyczy wprowadzenia czasowego podatku od nadzwyczajnych zysków osiąganych przez przedsiębiorstwa zajmujące się produkcją i handlem paliwami sprowadzanymi z zagranicy. Nowe przepisy pomogą sfinansować rządowe działania, które mają chronić obywateli przed skutkami wzrostu cen paliw wywołanego kryzysem na światowych rynkach energii, czyli tzw. CPN.","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-09-15","document_date":"2026-09-15","change_date":"2026-09-24T13:09:30Z","closure_date":"2026-09-18","passed":true,"urgency_status":"NORMAL","eu_related":false,"prints_considered_jointly":[]}','[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2026-09-15","print_number":"3100","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania na posiedzeniu Sejmu","stage_type":"ReadingReferral","date":"2026-09-15","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-09-15","committee_code":"Sejm","sub_committee":false,"children":[]}]}]','bbeea684b8e4569cfb9c232b3d502bf1f88c5848b793e1bb671279582a313602',NULL,0,'text prefilter: no keyword hits','2026-09-15T15:46:11+00:00','2026-09-25T02:53:32+00:00','{"term":10,"number":"RPW/31041/2026","title":"Rządowy projekt ustawy o podatku od nadzwyczajnych zysków osiągniętych w okresie od marca do grudnia 2026 r. ze zbycia paliw ciekłych","description":"wprowadzenia czasowego podatku od nadzwyczajnych zysków osiąganych przez przedsiębiorstwa zajmujące się produkcją i handlem paliwami sprowadzanymi z zagranicy. Nowe przepisy pomogą sfinansować rządowe działania, które mają chronić obywateli przed skutkami wzrostu cen paliw wywołanego kryzysem na światowych rynkach energii, czyli tzw. CPN.","applicant":"government","status":"ACTIVE","submission_type":"BILL","date_of_receipt":"2026-09-15","print_number":null,"eu_related":false,"public_consultation":false,"consultation_start":null,"consultation_end":null,"consultation_results":false,"withdrawn_date":null}','RPW/31041/2026',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,NULL,NULL);
INSERT INTO "bills" VALUES(10,'3101','Rządowy projekt ustawy o zmianie ustawy - Prawo o ruchu drogowym oraz niektórych innych ustaw','2026-09-18T12:28:20+00:00',NULL,0,'skipped_text_prefilter','[]','{"term":10,"number":"3101","title":"Rządowy projekt ustawy o zmianie ustawy - Prawo o ruchu drogowym oraz niektórych innych ustaw","description":"projekt dotyczy ograniczenia liczby zdarzeń drogowych na przejazdach kolejowych poprzez: 1) wprowadzenie instrumentu natychmiastowego zatrzymania na 3 miesiące prawa jazdy za najbardziej niebezpieczne naruszenia popełnione na przejazdach kolejowych, 2) zaostrzenie sądowego środka karnego w postaci zakazu prowadzenia pojazdów w przypadku przestępstw popełnionych na przejazdach kolejowych.","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-09-15","document_date":"2026-09-15","change_date":"2026-09-18T12:28:20Z","passed":false,"urgency_status":"NORMAL","eu_related":false,"prints_considered_jointly":[]}',NULL,NULL,NULL,0,'text prefilter: no keyword hits','2026-09-15T15:46:15+00:00','2026-09-19T13:56:39+00:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,NULL,NULL);
