INSERT INTO "bills" VALUES(10,'3102','Rządowy projekt ustawy o zmianie ustawy - Prawo energetyczne oraz niektórych innych ustaw','2026-09-24T13:20:34+00:00','2026-09-18',1,'analyzed','["text:migracja"]','{"term":10,"number":"3102","title":"Rządowy projekt ustawy o zmianie ustawy - Prawo energetyczne oraz niektórych innych ustaw","description":"projekt dotyczy zwiększenia bezpieczeństwa i efektywności funkcjonowania rynku energii elektrycznej. Nowe przepisy porządkują zasady działania centralnego systemu informacji rynku energii, ułatwią rozliczenia w przypadku problemów z systemami informatycznymi oraz wzmocnią obowiązek przekazywania danych potrzebnych do bezpiecznego zarządzania siecią. Projekt upraszcza także rozliczenia związane z ograniczeniami w poborze energii i porządkuje zasady dotyczące liczników zdalnego odczytu.","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-09-15","document_date":"2026-09-15","change_date":"2026-09-24T13:20:34Z","closure_date":"2026-09-18","passed":true,"urgency_status":"NORMAL","eu_related":false,"prints_considered_jointly":[]}','[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2026-09-15","print_number":"3102","sub_committee":false,"children":[]},{"stage_name":"Skierowano do I czytania w komisjach","stage_type":"ReadingReferral","date":"2026-09-15","sub_committee":false,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2026-09-15","committee_code":"ESK","sub_committee":false,"children":[]}]}]','f1cfef79e40f24a3fed5c5b6818882fff2dc2583555703529b4c5b38c8e8ad13','{"analysis":{"relevant":false,"score":1,"category":"none","summary":"Законопроект касается технических и организационных аспектов рынка электроэнергии (CSIRE, счётчики, расчёты) и не затрагивает права, статус или процедуры для иностранцев.","key_changes":[],"affected_groups":[],"practical_impact":"","effective_date":null,"confidence":0.9,"rationale":"Законопроект касается технических и организационных аспектов рынка электроэнергии (CSIRE, счётчики, расчёты) и не затрагивает права, статус или процедуры для иностранцев.","changes_since_previous":[]},"model":"claude-sonnet-5","prompt_version":"2026-09-v7","input_chars":12605,"truncated":true,"text_source":"excerpts","created_at":"2026-09-15T19:44:19Z","input_tokens":7500,"output_tokens":96,"cache_read_input_tokens":null,"cache_creation_input_tokens":null,"source_url":null,"source_kind":"print","revision":1,"text_sha256":null,"source_checked_at":null}',0,NULL,'2026-09-15T19:43:24+00:00','2026-09-25T02:53:32+00:00','{"term":10,"number":"RPW/31043/2026","title":"Rządowy projekt ustawy o zmianie ustawy - Prawo energetyczne oraz niektórych innych ustaw","description":"zwiększenia bezpieczeństwa i efektywności funkcjonowania rynku energii elektrycznej. Nowe przepisy porządkują zasady działania centralnego systemu informacji rynku energii, ułatwią rozliczenia w przypadku problemów z systemami informatycznymi oraz wzmocnią obowiązek przekazywania danych potrzebnych do bezpiecznego zarządzania siecią. Projekt upraszcza także rozliczenia związane z ograniczeniami w poborze energii i porządkuje zasady dotyczące liczników zdalnego odczytu.","applicant":"government","status":"ACTIVE","submission_type":"BILL","date_of_receipt":"2026-09-15","print_number":"3102","eu_related":false,"public_consultation":false,"consultation_start":null,"consultation_end":null,"consultation_results":false,"withdrawn_date":null}',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,NULL,NULL);
