INSERT INTO "bills" VALUES(10,'RCL/12403400','Projekt ustawy o wyrobach budowlanych','2026-09-24T00:00:00+00:00',NULL,NULL,'skipped_text_prefilter','[]','{"term":10,"number":"RCL/12403400","title":"Projekt ustawy o wyrobach budowlanych","description":"BUDOWLANE WYROBY; budownictwo, lokalne planowanie i zagospodarowanie przestrzenne oraz mieszkalnictwo. Numer i tytuł aktu prawnego Unii Europejskiej: Rozporządzenie Parlamentu Europejskiego i Rady (UE) 2024/3110 z dnia 27 listopada 2024 r. w sprawie ustanowienia zharmonizowanych zasad wprowadzania do obrotu wyrobów budowlanych i uchylenia rozporządzenia (UE) nr 305/2011; Rozporządzenie Parlamentu Europejskiego i Rady (UE) 2019/1020 z dnia 20 czerwca 2019 r. w sprawie nadzoru rynku i zgodności produktów oraz zmieniające dyrektywę 2004/42/WE oraz rozporządzenia (WE) nr 765/2008 i (UE) nr 305/2011","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2025-10-21","document_date":"2025-10-21","change_date":"2026-09-24T00:00:00Z","eu_related":true,"rcl_link":"https://legislacja.rcl.gov.pl/projekt/12403400","prints_considered_jointly":[],"applicant":"government"}','[{"stage_name":"2. Uzgodnienia","stage_type":"RclStage","sub_committee":false,"children":[]},{"stage_name":"3. Konsultacje publiczne","stage_type":"RclStage","sub_committee":false,"children":[]},{"stage_name":"4. Opiniowanie","stage_type":"RclStage","sub_committee":false,"children":[]}]','2cf3a502c82cc64885ec41815f4edd2b0a8057ac90c7f484ffc0705729d3bb43',NULL,0,'text prefilter: no keyword hits','2026-09-16T19:36:18+00:00','2026-09-24T20:01:35+00:00',NULL,NULL,NULL,NULL,NULL,NULL,'{"id":12403400,"title":"Projekt ustawy o wyrobach budowlanych","applicant":"Minister Finansów i Gospodarki","wykaz_number":"UC117","wykaz_url":"https://www.gov.pl/web/premier/projekt-ustawy-o-wyrobach-budowlanych ","created":"2025-10-21","modified":"2026-09-16","departments":["budownictwo, lokalne planowanie i zagospodarowanie przestrzenne oraz mieszkalnictwo"]