INSERT INTO "bills" VALUES(10,'604','Poselski projekt ustawy o zmianie ustawy o Krajowej Administracji Skarbowej','2026-09-18T11:17:15+00:00',NULL,0,'skipped_text_prefilter','[]','{"term":10,"number":"604","title":"Poselski projekt ustawy o zmianie ustawy o Krajowej Administracji Skarbowej","description":"projekt dotyczy przywrócenia (obowiązującego przed dniem 1 lipca 2022 r.) rozwiązania polegającego na tym, że informacje o rachunku bankowym są przekazywane organom Krajowej Administracji Skarbowej, na ich żądanie, wobec podejrzanego o popełnienie przestępstwa lub wykroczenia oraz przestępstwa skarbowego lub wykroczenia skarbowego, a nie każdej osobie fizycznej","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2024-07-23","document_date":"2024-07-23","change_date":"2026-09-18T11:17:15Z","passed":false,"urgency_status":"NORMAL","eu_related":false,"prints_considered_jointly":[]}',NULL,NULL,NULL,0,'text prefilter: no keyword hits','2026-09-18T19:03:48+00:00','2026-09-19T13:56:39+00:00','{"term":10,"number":"SH-020-185/24","title":"Poselski projekt ustawy o zmianie ustawy o Krajowej Administracji Skarbowej","description":"przywrócenia (obowiązującego przed dniem 1 lipca 2022 r.) rozwiązania polegającego na tym, że informacje o rachunku bankowym są przekazywane organom Krajowej Administracji Skarbowej, na ich żądanie, wobec podejrzanego o popełnienie przestępstwa lub wykroczenia oraz przestępstwa skarbowego lub wykroczenia skarbowego, a nie każdej osobie fizycznej","applicant":"deputies","status":"ACTIVE","submission_type":"BILL","date_of_receipt":"2024-07-23","print_number":"604","eu_related":false,"public_consultation":false,"consultation_start":null,"consultation_end":null,"consultation_results":false,"withdrawn_date":null}',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,NULL,NULL);
INSERT INTO "bills" VALUES(10,'2644','Rządowy projekt ustawy o zabezpieczeniu socjalnym osób wykonujących zawód artystyczny','2026-09-18T13:33:03+00:00',NULL,0,'analyzed','["text:cudzoziemcy", "text:uchodzcy", "text:wizy", "text:zezwolenie_pobyt", "text:pobyt_kwalifikowany", "text:ochrona_miedzynarodowa", "text:status_uchodzcy", "text:obywatele_innych_panstw"]','{"term":10,"number":"2644","title":"Rządowy projekt ustawy o zabezpieczeniu socjalnym osób wykonujących zawód artystyczny","description":"projekt dotyczy włączenie artystów zawodowych do systemu zabezpieczenia społecznego; stworzenia możliwości aplikowania o przyznanie im uprawnienia do otrzymania dopłaty celem uzupełnienia finansowania ich składek na ubezpieczenia społeczne i zdrowotne do poziomu składek wynikających z minimalnego wynagrodzenia za pracę. Dopłata ma obejmować również składki na Fundusz Pracy oraz Fundusz Emerytur Pomostowych. Artyści osiągający tym samym najniższe dochody będą uprawnieni do wsparcia finansowego w opłaceniu składek w okresach, w których ich własne dochody nie będą pozwalać na pokrycie składek.","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-06-03","document_date":"2026-06-03","change_date":"2026-09-18T13:33:03Z","passed":false,"urgency_status":"NORMAL","eu_related":false,"rcl_num":"RM-0610-79-26","rcl_link":"https://legislacja.rcl.gov.pl/getIdFromLegislacja?number=RM-0610-79-26","prints_considered_jointly":[],"stages":[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2026-06-03","print_number":"2644","sitting_num":null,"decision":null,"committee_code":null,"report_file":null,"text_after3":null,"position":null,"proposal":null,"sub_committee":false,"minority_motions":null,"voting":null,"committee_name":null,"children":[]},{"stage_name":"Skierowano do I czytania na posiedzeniu Sejmu","stage_type":"ReadingReferral","date":"2026-06-09","print_number":null,"sitting_num":null,"decision":null,"committee_code":null,"report_