INSERT INTO "publications" VALUES(52,10,'1929','status_update','sent','@lex_inform_pl',56,'[]',11,'2026-09-18T09:56:11+00:00','2026-09-18T09:56:12+00:00',NULL,0,NULL,NULL,'{"bill_json":"{\"summary\":{\"term\":10,\"number\":\"1929\",\"title\":\"Rządowy projekt ustawy o asystencji osobistej osób z niepełnosprawnościami\",\"description\":\"projekt dotyczy systemowego uregulowania usługi asystencji osobistej jako obligatoryjnego i powszechnie dostępnego, w wybranej przez osobę z niepełnosprawnością formie, instrumentu wsparcia w codziennym funkcjonowaniu  m.in. przemieszczaniu się, prowadzeniu domu, załatwianiu spraw urzędowych, a także w pracy, nauce i kontaktach społecznych\",\"document_type\":\"projekt ustawy\",\"document_type_enum\":\"BILL\",\"process_start_date\":\"2025-11-04\",\"document_date\":\"2025-11-04\",\"change_date\":\"2026-09-18T09:10:25Z\",\"closure_date\":\"2026-09-18\",\"passed\":true,\"urgency_status\":\"NORMAL\",\"eu_related\":false,\"rcl_num\":\"RM-0610-188-25\",\"rcl_link\":\"https://legislacja.rcl.gov.pl/getIdFromLegislacja?number=RM-0610-188-25\",\"prints_considered_jointly\":[\"316\",\"1933\"],\"applicant\":null,\"eli\":null,\"display_address\":null,\"isap_url\":null},\"status\":\"analyzed\",\"prefilter_hits\":[\"text:cudzoziemcy\",\"text:uchodzcy\",\"text:obywatelstwo\",\"text:wizy\",\"text:zezwolenie_pobyt\",\"text:pobyt_kwalifikowany\",\"text:ochrona_miedzynarodowa\",\"text:status_uchodzcy\"],\"stages\":[{\"stage_name\":\"Projekt wpłynął do Sejmu\",\"stage_type\":\"Start\",\"date\":\"2025-11-04\",\"print_number\":\"1929\",\"sitting_num\":null,\"decision\":null,\"committee_code\":null,\"report_file\":null,\"text_after3\":null,\"position\":null,\"proposal\":null,\"sub_committee\":false,\"minority_motions\":null,\"voting\":null,\"committee_name\":null,\"children\":[]},{\"stage_name\":\"Skierowano do I czytania na posiedzeniu Sejmu\",\"stage_type\":\"ReadingReferral\",\"date\":\"2025-11-07\",\"print_number\":null,\"sitting_num\":null,\"decision\"